"""Exception hierarchy for the append-only key-value store."""

from __future__ import annotations

from pathlib import Path


class KVStoreError(Exception):
    """Base error for kvstore failures."""


class RecordError(KVStoreError):
    """A single on-disk record could not be decoded."""


class IncompleteRecordError(RecordError):
    """Not enough bytes are available to form a complete record."""


class CorruptRecordError(RecordError):
    """The bytes are present but the record is structurally invalid."""


class CorruptSegmentError(KVStoreError):
    """A complete record in a segment file is corrupt."""

    def __init__(self, path: Path, offset: int, reason: str) -> None:
        self.path = path if isinstance(path, Path) else Path(path)
        self.offset = offset
        self.reason = reason
        super().__init__(f"{self.path.name} offset {offset}: {reason}")

"""Binary record codec: 15-byte header plus UTF-8 key and value."""

from __future__ import annotations

import struct
import zlib

from kvstore.errors import CorruptRecordError, IncompleteRecordError

MAGIC = b"KVR1"
FLAG_VALUE = 0x00
FLAG_TOMBSTONE = 0x01
HEADER_SIZE = 15
HEADER_STRUCT = struct.Struct(">4sBHII")


def encode_record(key: str, value: str | None) -> bytes:
    key_bytes = key.encode("utf-8")
    if value is None:
        flags = FLAG_TOMBSTONE
        value_bytes = b""
    else:
        flags = FLAG_VALUE
        value_bytes = value.encode("utf-8")
    crc = zlib.crc32(key_bytes + value_bytes) & 0xFFFFFFFF
    header = HEADER_STRUCT.pack(MAGIC, flags, len(key_bytes), len(value_bytes), crc)
    return header + key_bytes + value_bytes


def decode_record(buf: bytes, offset: int = 0) -> tuple[str, str | None, int]:
    available = len(buf) - offset
    if available < HEADER_SIZE:
        raise IncompleteRecordError("truncated header")
    magic, flags, key_len, value_len, crc = HEADER_STRUCT.unpack_from(buf, offset)
    total = HEADER_SIZE + key_len + value_len
    if available < total:
        raise IncompleteRecordError("truncated payload")
    _check_structure(magic, flags, key_len, value_len)
    start = offset + HEADER_SIZE
    key_bytes = buf[start : start + key_len]
    value_bytes = buf[start + key_len : start + key_len + value_len]
    actual = zlib.crc32(key_bytes + value_bytes) & 0xFFFFFFFF
    if actual != crc:
        raise CorruptRecordError("crc mismatch")
    key, value_str = _decode_utf8(key_bytes, value_bytes)
    return key, (None if flags == FLAG_TOMBSTONE else value_str), total


def _check_structure(magic: bytes, flags: int, key_len: int, value_len: int) -> None:
    if magic != MAGIC:
        raise CorruptRecordError("bad magic")
    if flags not in (FLAG_VALUE, FLAG_TOMBSTONE):
        raise CorruptRecordError("unknown flags")
    if key_len == 0:
        raise CorruptRecordError("empty key")
    if flags == FLAG_TOMBSTONE and value_len != 0:
        raise CorruptRecordError("tombstone with value")


def _decode_utf8(key_bytes: bytes, value_bytes: bytes) -> tuple[str, str]:
    try:
        return key_bytes.decode("utf-8"), value_bytes.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise CorruptRecordError("invalid utf-8") from exc

"""One append-only segment file (`NNNNNN.seg`)."""

from __future__ import annotations

import os
import re
from collections.abc import Iterator
from pathlib import Path

from kvstore.errors import CorruptRecordError, CorruptSegmentError, IncompleteRecordError
from kvstore.record import decode_record

SEG_NAME_RE = re.compile(r"^\d{6}\.seg$")


def segment_filename(seg_id: int) -> str:
    return f"{seg_id:06d}.seg"


def segment_path(root: Path, seg_id: int) -> Path:
    return Path(root) / segment_filename(seg_id)


def list_segment_ids(root: Path) -> list[int]:
    ids: list[int] = []
    if not root.exists():
        return ids
    for entry in root.iterdir():
        if entry.is_file() and SEG_NAME_RE.match(entry.name):
            ids.append(int(entry.name[:6]))
    ids.sort()
    return ids


class Segment:
    def __init__(self, path: Path, seg_id: int) -> None:
        self._path = Path(path)
        self._seg_id = seg_id
        self._file = open(self._path, "a+b")
        self._file.seek(0, os.SEEK_END)
        self._committed = self._file.tell()
        self._closed = False

    @property
    def seg_id(self) -> int:
        return self._seg_id

    @property
    def path(self) -> Path:
        return self._path

    @property
    def size(self) -> int:
        if self._closed:
            return self._path.stat().st_size
        self._file.flush()
        return os.fstat(self._file.fileno()).st_size

    def append(self, blob: bytes) -> int:
        self._ensure_open()
        self._file.seek(self._committed)
        self._file.truncate(self._committed)
        offset = self._committed
        self._file.write(blob)
        self._file.flush()
        os.fsync(self._file.fileno())
        self._committed += len(blob)
        return offset

    def scan(self) -> Iterator[tuple[str, str | None, int]]:
        self._ensure_open()
        self._file.seek(0)
        data = self._file.read()
        offset = 0
        while True:
            try:
                key, value, size = decode_record(data, offset)
            except IncompleteRecordError:
                break
            except CorruptRecordError as exc:
                raise CorruptSegmentError(self._path, offset, str(exc)) from exc
            yield key, value, offset
            offset += size
        self._committed = offset
        self._file.seek(0, os.SEEK_END)

    def close(self) -> None:
        if not self._closed:
            self._file.close()
            self._closed = True

    def _ensure_open(self) -> None:
        if self._closed:
            raise ValueError("segment is closed")

"""In-memory map from key to the newest on-disk location."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class Location:
    seg_id: int
    offset: int


class Index:
    def __init__(self) -> None:
        self._live: dict[str, Location] = {}
        self._tombstones: dict[str, Location] = {}

    def put(self, key: str, loc: Location, *, tombstone: bool) -> None:
        if tombstone:
            self._live.pop(key, None)
            self._tombstones[key] = loc
        else:
            self._tombstones.pop(key, None)
            self._live[key] = loc

    def get(self, key: str) -> Location | None:
        return self._live.get(key)

    def live_keys(self) -> list[str]:
        return sorted(
            self._live,
            key=lambda k: (self._live[k].seg_id, self._live[k].offset),
        )

    def tombstone_count(self) -> int:
        return len(self._tombstones)

    def __len__(self) -> int:
        return len(self._live)

"""Durable key-value store over append-only segment files."""

from __future__ import annotations

import os
from dataclasses import dataclass
from pathlib import Path

from kvstore.errors import CorruptRecordError, CorruptSegmentError
from kvstore.index import Index, Location
from kvstore.record import decode_record, encode_record
from kvstore.segment import Segment, list_segment_ids, segment_path


@dataclass(frozen=True)
class Stats:
    live_keys: int
    tombstones: int
    total_records: int
    dead_records: int
    segment_count: int
    bytes_on_disk: int


class KVStore:
    def __init__(self, root: str | os.PathLike[str], *, max_segment_bytes: int = 4096) -> None:
        if not isinstance(max_segment_bytes, int) or isinstance(max_segment_bytes, bool):
            raise ValueError("max_segment_bytes must be an int")
        if max_segment_bytes < 16:
            raise ValueError("max_segment_bytes must be >= 16")
        self._root = Path(root)
        self._root.mkdir(parents=True, exist_ok=True)
        self._max_segment_bytes = max_segment_bytes
        self._index = Index()
        self._cache: dict[str, str] = {}
        self._total_records = 0
        self._closed = False
        self._active = self._recover()

    def set(self, key: str, value: str) -> None:
        self._ensure_open()
        _validate_key(key)
        if not isinstance(value, str):
            raise TypeError("value must be str")
        self._write(key, value)

    def get(self, key: str) -> str | None:
        self._ensure_open()
        _validate_key(key)
        if self._index.get(key) is None:
            return None
        return self._cache.get(key)

    def delete(self, key: str) -> bool:
        self._ensure_open()
        _validate_key(key)
        if self._index.get(key) is None:
            return False
        self._write(key, None)
        return True

    def keys(self) -> list[str]:
        self._ensure_open()
        return self._index.live_keys()

    def stats(self) -> Stats:
        self._ensure_open()
        live = len(self._index)
        tombs = self._index.tombstone_count()
        ids = list_segment_ids(self._root)
        nbytes = sum(segment_path(self._root, i).stat().st_size for i in ids)
        return Stats(live, tombs, self._total_records, self._total_records - live - tombs, len(ids), nbytes)

    def close(self) -> None:
        if not self._closed:
            self._active.close()
            self._closed = True

    def __enter__(self) -> KVStore:
        return self

    def __exit__(self, *exc: object) -> None:
        self.close()

    def _recover(self) -> Segment:
        ids = list_segment_ids(self._root)
        if not ids:
            return Segment(segment_path(self._root, 1), 1)
        for seg_id in ids[:-1]:
            seg = Segment(segment_path(self._root, seg_id), seg_id)
            try:
                self._ingest(seg)
            finally:
                seg.close()
        active = Segment(segment_path(self._root, ids[-1]), ids[-1])
        self._ingest(active)
        return active

    def _ingest(self, seg: Segment) -> None:
        for key, value, offset in seg.scan():
            self._total_records += 1
            self._apply(key, value, Location(seg.seg_id, offset))

    def _write(self, key: str, value: str | None) -> None:
        blob = encode_record(key, value)
        n = len(blob)
        if self._active.size != 0 and self._active.size + n > self._max_segment_bytes:
            new_id = self._active.seg_id + 1
            self._active.close()
            self._active = Segment(segment_path(self._root, new_id), new_id)
        offset = self._active.append(blob)
        self._total_records += 1
        self._apply(key, value, Location(self._active.seg_id, offset))

    def _apply(self, key: str, value: str | None, loc: Location) -> None:
        self._index.put(key, loc, tombstone=value is None)
        if value is None:
            self._cache.pop(key, None)
        else:
            self._cache[key] = value

    def _ensure_open(self) -> None:
        if self._closed:
            raise ValueError("store is closed")

    def _install_compacted(
        self,
        active: Segment,
        index: Index,
        cache: dict[str, str],
        total_records: int,
    ) -> None:
        self._active = active
        self._index = index
        self._cache = cache
        self._total_records = total_records


def _validate_key(key: object) -> None:
    if not isinstance(key, str):
        raise TypeError("key must be str")
    n = len(key.encode("utf-8"))
    if n < 1 or n > 65535:
        raise ValueError("key UTF-8 length must be in 1..65535")


def read_record_at(path: Path, offset: int) -> tuple[str, str | None]:
    with open(path, "rb") as fh:
        fh.seek(offset)
        data = fh.read()
    try:
        key, value, _size = decode_record(data, 0)
    except CorruptRecordError as exc:
        raise CorruptSegmentError(path, offset, str(exc)) from exc
    return key, value

"""CLI: python -m kvstore ROOT COMMAND [ARGS...]"""

from __future__ import annotations

import argparse
import sys

from kvstore.compact import compact
from kvstore.errors import CorruptSegmentError
from kvstore.store import KVStore


def main(argv: list[str] | None = None) -> int:
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        code = exc.code
        if code in (0, None):
            return 0
        return int(code)
    try:
        return _run(args)
    except CorruptSegmentError as exc:
        print(str(exc), file=sys.stderr)
        return 3
    except (ValueError, TypeError) as exc:
        print(str(exc), file=sys.stderr)
        return 2


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="kvstore")
    parser.add_argument("--max-segment-bytes", type=_positive_int, default=4096)
    parser.add_argument("root")
    sub = parser.add_subparsers(dest="command", required=True)
    p_set = sub.add_parser("set")
    p_set.add_argument("key")
    p_set.add_argument("value")
    p_get = sub.add_parser("get")
    p_get.add_argument("key")
    p_del = sub.add_parser("delete")
    p_del.add_argument("key")
    sub.add_parser("list")
    sub.add_parser("compact")
    sub.add_parser("stats")
    return parser


def _positive_int(text: str) -> int:
    try:
        value = int(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError("max-segment-bytes must be a positive integer") from exc
    if value <= 0:
        raise argparse.ArgumentTypeError("max-segment-bytes must be a positive integer")
    return value


def _run(args: argparse.Namespace) -> int:
    with KVStore(args.root, max_segment_bytes=args.max_segment_bytes) as store:
        command = args.command
        if command == "set":
            store.set(args.key, args.value)
            return 0
        if command == "get":
            value = store.get(args.key)
            if value is None:
                return 1
            sys.stdout.write(value + "\n")
            return 0
        if command == "delete":
            return 0 if store.delete(args.key) else 1
        if command == "list":
            for key in store.keys():
                sys.stdout.write(key + "\n")
            return 0
        if command == "compact":
            result = compact(store)
            line = (
                f"removed={result.segments_removed} written={result.records_written} "
                f"dropped={result.records_dropped} reclaimed={result.bytes_reclaimed}\n"
            )
            sys.stdout.write(line)
            return 0
        if command == "stats":
            s = store.stats()
            sys.stdout.write(
                f"live_keys={s.live_keys} tombstones={s.tombstones} "
                f"total_records={s.total_records} dead_records={s.dead_records} "
                f"segment_count={s.segment_count} bytes_on_disk={s.bytes_on_disk}\n"
            )
            return 0
        return 2


if __name__ == "__main__":
    sys.exit(main())

